{
  "corrected": "My name is Karthik, and I have two years of experience in sales.",
  "mistakes": [
    {
      "wrong": "Myself Karthik",
      "right": "My name is Karthik",
      "type": "grammar",
      "explanation_tamil": "உங்களை அறிமுகப்படுத்தும்போது 'My name is' என்று சொல்ல வேண்டும்."
    },
    {
      "wrong": "I am having",
      "right": "I have",
      "type": "grammar",
      "explanation_tamil": "கடந்த கால அனுபவத்தைக் கூறும்போது 'have' பயன்படுத்த வேண்டும்."
    }
  ]
}

{
  "corrected": "I have been working in this company since 2019.",
  "mistakes": [
    {
      "wrong": "I am working",
      "right": "I have been working",
      "type": "grammar",
      "explanation_tamil": "தொடர்ந்து செய்யும் செயல்களைக் கூற 'have been' பயன்படுத்த வேண்டும்."
    }
  ]
}

{
  "corrected": "Please revert to me today.",
  "mistakes": [
    {
      "wrong": "revert back",
      "right": "revert",
      "type": "grammar",
      "explanation_tamil": "revert என்பது போதுமானது, back தேவையில்லை."
    }
  ]
}

{
  "corrected": "We discussed the budget, and he said it was fine.",
  "mistakes": [
    {
      "wrong": "discussed about",
      "right": "discussed",
      "type": "grammar",
      "explanation_tamil": "Discuss உடன் 'about' தேவையில்லை."
    },
    {
      "wrong": "told that it is fine",
      "right": "said it was fine",
      "type": "style",
      "explanation_tamil": "Professional English-ல் 'told that' என்பதை 'said' என்று பயன்படுத்துவது சிறந்தது."
    }
  ]
}

{
  "corrected": "Please do the needful and send the files.",
  "mistakes": [
    {
      "wrong": "Kindly",
      "right": "Please",
      "type": "style",
      "explanation_tamil": "Kindly என்பதற்குப் பதிலாக Please பயன்படுத்துவது மிகவும் தொழில்முறை."
    }
  ]
}

{
  "corrected": "What is your name?",
  "mistakes": [
    {
      "wrong": "good name",
      "right": "name",
      "type": "style",
      "explanation_tamil": "உங்கள் பெயர் என்ன என்று கேட்க வேண்டும்."
    }
  ]
}

{
  "corrected": "I have been working here for three years and I enjoy my role.",
  "mistakes": [
    {
      "wrong": "I have been working here for three years and I enjoy my role.",
      "right": "I have been working here for three years and I enjoy my role.",
      "type": "style",
      "explanation_tamil": "இந்த வாக்கியம் இலக்கணப்படி சரியானது மற்றும் தொழில்முறைக்கு ஏற்றது."
    }
  ]
}

